const mergeDuplicateWorks = (clientId, callback) => {
  Client.findById(clientId, (err, client) => {
    const bigQuery = new BigQuery({
      datasetName: client.bigQueryDataset,
      inputTable: client.bigQuerySalesTable,
      outputTable: client.bigQueryPeriodSales,
      costsTable: client.bigQueryPeriodCosts,
    });

    waterfall([
      (cb) => {
        console.log(works.length);

        const keepWorks = works.filter(work => work.delete === false);
        const deleteWorks = works.filter(work => work.delete === true);

        console.log(keepWorks.length);
        console.log(deleteWorks.length);

        cb(null, keepWorks, deleteWorks);
      },
      (keepWorks, deleteWorks, cb) => {
        let count = 0;
        eachLimit(keepWorks, 10, (keepWork, eachCb) => {
          Work.findById(keepWork._id, (findErr, work) => {
            if (findErr) { return eachCb(findErr); }

            if (!work) {
              logger.error(`Could not find work for ${keepWork._id} - ${keepWork.title}`);
              return eachCb();
            }

            worksToMerge = deleteWorks.filter(item => item.title === keepWork.title);
            eachSeries(worksToMerge, (workToMerge, eachSeriesCb) => {
              Work.findById(workToMerge._id, (findMergeErr, workMerge) => {
                if (findMergeErr) { return eachSeriesCb(findMergeErr); }
      
                if (!workMerge) {
                  logger.error(`Could not find work for ${workToMerge._id} - ${workToMerge.title}`);
                  return eachSeriesCb();
                }
                if (Array.isArray(workMerge.societyIdentifiers) && workMerge.societyIdentifiers.length > 0) {
                  logger.info(`Merging ${workMerge.societyIdentifiers} into ${work.societyIdentifiers}`);
                  workMerge.societyIdentifiers.forEach(societyIdentifier => {
                    if (!work.societyIdentifiers.includes(societyIdentifier)) {
                      work.societyIdentifiers = [...work.societyIdentifiers, societyIdentifier];
                    }
                  });
                }

                if (Array.isArray(workMerge.aliases) && workMerge.aliases.length > 0) {
                  logger.info(`Merging ${workMerge.aliases} into ${work.aliases}`);
                  workMerge.aliases.forEach(aliase => {
                    if (!work.aliases.includes(aliase)) {
                      work.aliases = [...work.aliases, aliase];
                    }
                  });
                }

                Work.findByIdAndRemove(workMerge._id.toString(), (err, res) => {
                  if (err) {
                    return eachSeriesCb(err);
                  }
                  if (res) {
                    console.log('Duplicate work removed ');
                    bigQuery.updateData(bigQuery.inputTable, { workId: workToMerge._id }, { workId: work._id.toString() }, (err, response) => {
                      console.log(response);
                      eachSeriesCb();
                    });
                  } else {
                    eachSeriesCb();
                  }
                });
              });
            }, () => {
              logger.info(`Saved ${work.title}`);
              work.save({ timestamps: false }, (err) => {
                count += 1;
                eachCb();
              });
            });
          })
        }, (err) => {
          logger.info(`Saved ${count} of ${keepWorks.length} works`);
          cb(err, deleteWorks);
        })
      },
    ], callback);
  });
}

const clientId = '629f70301c406d00246b8723';

mergeDuplicateWorks(clientId, (err) => {
  if (err) { logger.error(err); }
  logger.info('Merge complete');
  process.exit(0);
});

